import { parseRetryAfter, computeRetryDelay } from './src/retryPolicy.js';
const now = Date.parse('2026-08-26T20:00:00Z');
// invalid delta-seconds
console.log('signed +5:', parseRetryAfter('+5', now)); // null expected
console.log('signed -5:', parseRetryAfter('-5', now)); // null expected
console.log('fractional 1.5:', parseRetryAfter('1.5', now)); // null expected
console.log('exp 1e3:', parseRetryAfter('1e3', now)); // null expected
console.log('hex 0x10:', parseRetryAfter('0x10', now)); // null expected
console.log('empty:', parseRetryAfter('', now)); // null
console.log('non-string 5:', parseRetryAfter(5, now)); // null
// past date
console.log('past date:', parseRetryAfter('Wed, 26 Aug 2026 19:00:00 GMT', now)); // 0
// http-date non-finite now
console.log('date nonfinite now:', parseRetryAfter('Wed, 26 Aug 2026 20:00:20 GMT', NaN)); // null
// delta-seconds no now needed
console.log('delta no now:', parseRetryAfter('5', undefined)); // 5000
// very large attempt
console.log('large attempt:', computeRetryDelay({ attempt: 1e9, retryAfter: null, nowMs: now })); // 300000
console.log('large attempt 100:', computeRetryDelay({ attempt: 100, retryAfter: null, nowMs: now })); // 300000
// retry-after cap
console.log('retryafter cap:', computeRetryDelay({ attempt: 1, retryAfter: '99999', nowMs: now })); // 300000
"

